// sql_node_CLcust pastes the id in as text: digits only
const rawId = [{{workflowparams:customer_id}}][0];
const cid = rawId === undefined || rawId === null ? "" : String(rawId).trim();
return { customerIdSql: /^[0-9]{1,20}$/.test(cid) ? cid : "0" };

// sql_node_CLcust's row as the get-node returned it: {count, data}, control_type_list parsed (a JSON column may arrive as text)
const rows = [{{node:sql_node_CLcust.data}}][0];
const found = Array.isArray(rows) ? rows : rows ? [rows] : [];
const record = Object.assign({}, found[0] || {});
if (typeof record.control_type_list === "string") {
  try {
    record.control_type_list = JSON.parse(record.control_type_list);
  } catch (e) {
    record.control_type_list = null;
  }
}
return { count: found.length, data: record };

const customerData = {{node:code_node_CLrow.data.data}};

const controlTypes = customerData.control_type_list;

const outstandingAmount =
  parseFloat(customerData.outstanding_balance || 0) || 0;
const overdueAmount =
  parseFloat(customerData.overdue_inv_total_amount || 0) || 0;
const overdueLimit = parseFloat(customerData.overdue_limit || 0) || 0;
const creditLimit =
  parseFloat(customerData.customer_credit_limit || 0) || 0;
const sqtTotal = parseFloat({{workflowparams:total}} || 0) || 0;
const revisedOutstandingAmount = outstandingAmount + sqtTotal;

const creditMetrics = {
  credit_limit: creditLimit,
  current_credit_amount: revisedOutstandingAmount,
  over_credit_amount: Math.max(
    0,
    revisedOutstandingAmount - creditLimit
  ),
};

// Helper function to add messages with calculated values
const formatMessage = (message, values = {}) => {
  let formattedMessage = message;

  if (values.creditLimit !== undefined) {
    formattedMessage += `<br><strong>Total Allowed Credit: ${values.creditLimit}</strong>`;
  }
  if (values.totalCredit !== undefined) {
    formattedMessage += `<br><strong>Total Credit: ${values.totalCredit}</strong>`;
  }
  if (values.overdueLimit !== undefined) {
    formattedMessage += `<br><strong>Total Allowed Overdue: ${values.overdueLimit}</strong>`;
  }
  if (values.totalOverdue !== undefined) {
    formattedMessage += `<br><strong>Total Overdue: ${values.totalOverdue}</strong>`;
  }

  return formattedMessage;
};

// Helper function to determine popup and create message
const determineMessage = (popupNumber, isBlock) => {
  const popupConfigs = {
    1: {
      alert: "Alert: Credit Limit Exceeded - Review Required",
      text: "The customer has exceeded the allowed credit limit.",
      showCredit: true,
      showOverdue: false,
      buttonText:
        "Please review the credit limit or adjust the order amount before issuing the " +
        {{workflowparams:document_type}} +
        ".",
    },
    2: {
      alert: "Alert: Overdue Limit Exceeded - Review Required",
      text: "The customer has exceeded the allowed overdue limit.",
      showCredit: false,
      showOverdue: true,
      buttonText: "Please review overdue invoices before proceeding.",
    },
    3: {
      alert:
        "Alert: Credit Limit and Overdue Limit Exceeded - Review Required",
      text: "The customer has exceeded both credit limit and overdue limit.",
      showCredit: true,
      showOverdue: true,
      buttonText: "Please review both limits before proceeding.",
    },
    4: {
      alert: "Alert: Overdue Limit Exceeded - Review Required",
      text: "The customer has exceeded the allowed overdue limit.",
      showCredit: false,
      showOverdue: true,
      buttonText: "Please confirm if you want to save it.",
    },
    5: {
      alert: "Alert: Credit Limit Exceeded - Review Required",
      text: "The customer has exceeded the allowed credit limit.",
      showCredit: true,
      showOverdue: false,
      buttonText: "Please confirm if you want to save it.",
    },
    6: {
      alert: "Customer Account Suspended",
      text: "This order cannot be processed at this time due to the customer's suspended account status.",
      showCredit: false,
      showOverdue: false,
      buttonText: null,
    },
    7: {
      alert:
        "Alert: Credit Limit and Overdue Limit Exceeded - Review Required",
      text: "The customer has exceeded both credit limit and overdue limit.",
      showCredit: true,
      showOverdue: true,
      buttonText: "Please confirm if you want to save it.",
    },
  };

  const config = popupConfigs[popupNumber];
  if (!config) return null;

  let prefix = isBlock ? "Block - " : "Override - ";
  let fullMessage = `${prefix}<span style="color: red;">${config.alert}.</span><br><br>${config.text}<br>`;

  if (config.showCredit) {
    fullMessage = formatMessage(fullMessage, {
      creditLimit,
      totalCredit: revisedOutstandingAmount,
    });
  }

  if (config.showOverdue) {
    fullMessage = formatMessage(fullMessage, {
      overdueLimit,
      totalOverdue: overdueAmount,
    });
  }

  if (config.buttonText) {
    fullMessage += ` <br>${config.buttonText}`;
  }

  return fullMessage;
};

// Check if control types exist
if (controlTypes && Array.isArray(controlTypes)) {
  // Define control type behaviors
  const controlTypeChecks = {
    0: () => {
      const message = formatMessage(
        "Control Type 0: Ignoring all credit/overdue checks. Allowed to proceed.",
        {
          creditLimit,
          totalCredit: revisedOutstandingAmount,
          overdueLimit,
          totalOverdue: overdueAmount,
        }
      );
      return { result: 'success', message };
    },
    1: () => {
      if (overdueAmount > overdueLimit) {
        const message = determineMessage(2, true);
        return { result: 'failed', message };
      }
      const message = formatMessage(
        "Control Type 1: Overdue limit check passed.",
        {
          overdueLimit,
          totalOverdue: overdueAmount,
        }
      );
      return { result: 'success', message };
    },
    2: () => {
      if (overdueAmount > overdueLimit) {
        const message = determineMessage(4, false);
        return { result: 'failed', message };
      }
      const message = formatMessage(
        "Control Type 2: Overdue limit check passed.",
        {
          overdueLimit,
          totalOverdue: overdueAmount,
        }
      );
      return { result: 'success', message };
    },
    3: () => {
      if (revisedOutstandingAmount > creditLimit) {
        const message = determineMessage(1, true);
        return { result: 'failed', message };
      }
      const message = formatMessage(
        "Control Type 3: Credit limit check passed.",
        {
          creditLimit,
          totalCredit: revisedOutstandingAmount,
        }
      );
      return { result: 'success', message };
    },
    4: () => {
      const creditExceeded = revisedOutstandingAmount > creditLimit;
      const overdueExceeded = overdueAmount > overdueLimit;

      if (creditExceeded && overdueExceeded) {
        const message = determineMessage(3, true);
        return { result: 'failed', message };
      } else if (creditExceeded) {
        const message = determineMessage(1, true);
        return { result: 'failed', message };
      } else if (overdueExceeded) {
        const message = determineMessage(2, true);
        return { result: 'failed', message };
      }

      const message = formatMessage(
        "Control Type 4: Both credit and overdue limits check passed.",
        {
          creditLimit,
          totalCredit: revisedOutstandingAmount,
          overdueLimit,
          totalOverdue: overdueAmount,
        }
      );
      return { result: 'success', message };
    },
    5: () => {
      const creditExceeded = revisedOutstandingAmount > creditLimit;
      const overdueExceeded = overdueAmount > overdueLimit;

      if (creditExceeded) {
        if (overdueExceeded) {
          const message = determineMessage(3, true);
          return { result: 'failed', message };
        } else {
          const message = determineMessage(1, true);
          return { result: 'failed', message };
        }
      } else if (overdueExceeded) {
        const message = determineMessage(4, false);
        return { result: 'failed', message };
      }

      const message = formatMessage("Control Type 5: All checks passed.", {
        creditLimit,
        totalCredit: revisedOutstandingAmount,
        overdueLimit,
        totalOverdue: overdueAmount,
      });
      return { result: 'success', message };
    },
    6: () => {
      if (revisedOutstandingAmount > creditLimit) {
        const message = determineMessage(5, false);
        return { result: 'failed', message };
      }

      const message = formatMessage(
        "Control Type 6: Credit limit check passed.",
        {
          creditLimit,
          totalCredit: revisedOutstandingAmount,
        }
      );
      return { result: 'success', message };
    },
    7: () => {
      const creditExceeded = revisedOutstandingAmount > creditLimit;
      const overdueExceeded = overdueAmount > overdueLimit;

      if (overdueExceeded) {
        const message = determineMessage(2, true);
        return { result: 'failed', message };
      } else if (creditExceeded) {
        const message = determineMessage(5, false);
        return { result: 'failed', message };
      }

      const message = formatMessage("Control Type 7: All checks passed.", {
        creditLimit,
        totalCredit: revisedOutstandingAmount,
        overdueLimit,
        totalOverdue: overdueAmount,
      });
      return { result: 'success', message };
    },
    8: () => {
      const creditExceeded = revisedOutstandingAmount > creditLimit;
      const overdueExceeded = overdueAmount > overdueLimit;

      if (creditExceeded && overdueExceeded) {
        const message = determineMessage(7, false);
        return { result: 'failed', message };
      } else if (creditExceeded) {
        const message = determineMessage(5, false);
        return { result: 'failed', message };
      } else if (overdueExceeded) {
        const message = determineMessage(4, false);
        return { result: 'failed', message };
      }

      const message = formatMessage("Control Type 8: All checks passed.", {
        creditLimit,
        totalCredit: revisedOutstandingAmount,
        overdueLimit,
        totalOverdue: overdueAmount,
      });
      return { result: 'success', message };
    },
    9: () => {
      const message = determineMessage(6, true);
      return { result: 'failed', message };
    },
  };

  // Get applicable control types for document
  const applicableControls = controlTypes
    .filter((ct) => ct.document_type === {{workflowparams:document_type}})
    .map((ct) => {
      const checkResult = controlTypeChecks[ct.control_type]
        ? controlTypeChecks[ct.control_type]()
        : {
            result: 'success',
            message: formatMessage(
              `Control Type ${ct.control_type}: Applied default behavior.`,
              {
                creditLimit,
                totalCredit: revisedOutstandingAmount,
                overdueLimit,
                totalOverdue: overdueAmount,
              }
            ),
          };
      return {
        ...checkResult,
        control_type: ct.control_type,
      };
    });

  // If no applicable controls found
  if (applicableControls.length === 0) {
    const message = formatMessage(
      "No control type defined for " +
        {{workflowparams:document_type}} +
        " document type. Proceeding with order.",
      {
        creditLimit,
        totalCredit: revisedOutstandingAmount,
        overdueLimit,
        totalOverdue: overdueAmount,
      }
    );
    return {
      result: 'success',
      message: message,
      ...creditMetrics,
    };
  }

  // Sort by priority: blocks first, then overrides, then successes
  const priorityOrder = {
    block: 1, // Block has highest priority
    override: 2, // Then override
    success: 3, // Then success
  };

  // Convert result types to priority keys
  const getPriorityKey = (result, message) => {
    if (result === 'failed') {
      return message.includes("Block - ") ? "block" : "override";
    }
    return "success";
  };

  applicableControls.forEach((control) => {
    control.priorityKey = getPriorityKey(control.result, control.message);
  });

  applicableControls.sort(
    (a, b) => priorityOrder[a.priorityKey] - priorityOrder[b.priorityKey]
  );

  // Return the highest priority result (first in sorted array)
  return {
    ...applicableControls[0],
    ...creditMetrics,
  };
} else {
  // No control types defined - allow with informational message
  const message = formatMessage(
    "No control type defined for customer. Proceeding with order.",
    {
      creditLimit,
      totalCredit: revisedOutstandingAmount,
      overdueLimit,
      totalOverdue: overdueAmount,
    }
  );
  return {
    result: 'success',
    message: message,
    ...creditMetrics,
  };
}
